From 8cdac7a0b32cc9f9fe09e7d6705408d662a2ab95 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:43:03 +0100
Subject: [PATCH] applets/taskmanager: show the app's source when two apps
 share a name

The same app installed from the distro and as a Flatpak or Snap showed
two identical tooltips. When another task has the same name, the tooltip
heading now says where the app came from, like "Firefox (Flatpak)".

BUG: 500695
---
 applets/taskmanager/backend.cpp             | 21 +++++++++++++++++++++
 applets/taskmanager/backend.h               |  1 +
 applets/taskmanager/qml/ToolTipDelegate.qml | 17 +++++++++++++++++
 applets/taskmanager/qml/ToolTipInstance.qml |  8 +++++---
 4 files changed, 44 insertions(+), 3 deletions(-)

diff --git a/applets/taskmanager/backend.cpp b/applets/taskmanager/backend.cpp
index 1005d2a981..9ff2d5da90 100644
--- a/applets/taskmanager/backend.cpp
+++ b/applets/taskmanager/backend.cpp
@@ -146,6 +146,27 @@ QStringList Backend::applicationCategories(const QUrl &launcherUrl)
     return desktopFile.desktopGroup().readXdgListEntry(QStringLiteral("Categories"));
 }

+QString Backend::applicationSource(const QUrl &launcherUrl)
+{
+    const QUrl desktopEntryUrl = tryDecodeApplicationsUrl(launcherUrl);
+
+    if (!desktopEntryUrl.isValid() || !desktopEntryUrl.isLocalFile() || !KDesktopFile::isDesktopFile(desktopEntryUrl.toLocalFile())) {
+        return QString();
+    }
+
+    KDesktopFile desktopFile(desktopEntryUrl.toLocalFile());
+    const KConfigGroup group = desktopFile.desktopGroup();
+
+    if (group.hasKey("X-Flatpak")) {
+        return i18nc("@info where an app was installed from", "Flatpak");
+    }
+    if (group.hasKey("X-SnapInstanceName")) {
+        return i18nc("@info where an app was installed from", "Snap");
+    }
+
+    return QString();
+}
+
 QVariantList Backend::jumpListActions(const QUrl &launcherUrl, QObject *parent)
 {
     QVariantList actions;
diff --git a/applets/taskmanager/backend.h b/applets/taskmanager/backend.h
index f95faee70b..e45fc52f85 100644
--- a/applets/taskmanager/backend.h
+++ b/applets/taskmanager/backend.h
@@ -67,6 +67,7 @@ public:

     Q_INVOKABLE static QUrl tryDecodeApplicationsUrl(const QUrl &launcherUrl);
     Q_INVOKABLE static QStringList applicationCategories(const QUrl &launcherUrl);
+    Q_INVOKABLE static QString applicationSource(const QUrl &launcherUrl);

     int screen() const;
     void setScreen(int screen);
diff --git a/applets/taskmanager/qml/ToolTipDelegate.qml b/applets/taskmanager/qml/ToolTipDelegate.qml
index 014e954c5c..17b6782ee4 100644
--- a/applets/taskmanager/qml/ToolTipDelegate.qml
+++ b/applets/taskmanager/qml/ToolTipDelegate.qml
@@ -17,6 +17,7 @@ import org.kde.plasma.core as PlasmaCore
 import org.kde.plasma.components as PlasmaComponents3
 import org.kde.plasma.private.mpris as Mpris
 import org.kde.kirigami as Kirigami
+import org.kde.taskmanager as TaskManager

 import org.kde.plasma.plasmoid

@@ -56,6 +57,22 @@ Loader {
     // This number controls the overall size of the window tooltips
     readonly property int tooltipInstanceMaximumWidth: Kirigami.Units.gridUnit * 16

+    // Only shown when another task has the same name, e.g. a distro package and a Flatpak
+    readonly property string appSource: {
+        const source = backend.applicationSource(launcherUrl);
+        if (source === "") {
+            return "";
+        }
+        for (let i = 0; i < tasksModel.count; ++i) {
+            const index = tasksModel.makeModelIndex(i);
+            if (tasksModel.data(index, TaskManager.AbstractTasksModel.AppName) === appName
+                && tasksModel.data(index, TaskManager.AbstractTasksModel.LauncherUrlWithoutIcon).toString() !== launcherUrl.toString()) {
+                return source;
+            }
+        }
+        return "";
+    }
+
     // These properties are required to make tooltip interactive when there is a player but no window is present.
     readonly property Mpris.PlayerContainer playerData: mpris2Source.playerForLauncherUrl(launcherUrl, pidParent)

diff --git a/applets/taskmanager/qml/ToolTipInstance.qml b/applets/taskmanager/qml/ToolTipInstance.qml
index 5a42d24a17..2749993deb 100644
--- a/applets/taskmanager/qml/ToolTipInstance.qml
+++ b/applets/taskmanager/qml/ToolTipInstance.qml
@@ -130,7 +130,9 @@ ColumnLayout {
                     Layout.fillWidth: true
                     lineHeight: toolTipDelegate.isWin && Plasmoid.configuration.showToolTips ? 1 : appNameHeading.lineHeight
                     elide: Text.ElideRight
-                    text: toolTipDelegate.appName
+                    text: toolTipDelegate.appSource !== ""
+                        ? i18nc("@title:tooltip %1 is an app name, %2 is where it was installed from, like Flatpak or Snap", "%1 (%2)", toolTipDelegate.appName, toolTipDelegate.appSource)
+                        : toolTipDelegate.appName
                     color: (headerHoverHandler.enabled && headerHoverHighlight.pressed) ? Kirigami.Theme.highlightedTextColor : Kirigami.Theme.textColor
                     opacity: root.index === 0 ? 1 : 0
                     visible: (text.length !== 0) && (root.orientation === ListView.Horizontal || root.index === 0)
@@ -154,7 +156,7 @@ ColumnLayout {
                     property bool somethingVisible: (thumbnailSourceItem.visible ||
                         appNameHeading.visible || subtext.visible)
                     text: ((root.titleIncludesTrack && playerController.active) ||
-                           (root.title === appNameHeading.text && somethingVisible))
+                           (root.title === toolTipDelegate.appName && somethingVisible))
                           ? "" : root.title
                     color: (headerHoverHandler.enabled && headerHoverHighlight.pressed) ? Kirigami.Theme.highlightedTextColor : Kirigami.Theme.textColor
                     opacity: 0.75
@@ -177,7 +179,7 @@ ColumnLayout {
                     text: toolTipDelegate.isWin ? root.generateSubText() : ""
                     color: (headerHoverHandler.enabled && headerHoverHighlight.pressed) ? Kirigami.Theme.highlightedTextColor : Kirigami.Theme.textColor
                     opacity: 0.75
-                    visible: text.length !== 0 && text !== appNameHeading.text
+                    visible: text.length !== 0 && text !== toolTipDelegate.appName
                     textFormat: Text.PlainText
                 }
             }
